declare(strict_types=1);

namespace PrestaShop\Module\Ckccategorycustomlinks\Install;

use Db;
use Module;
use PrestaShop\Module\Ckccategorycustomlinks\Sql\SqlQueries;

if (!defined('_PS_VERSION_')) {
    exit;
}

/**
 * Class Installer
 * @package PrestaShop\Module\Ckccategorycustomlinks\Install
 */
class Installer
{
    /**
     * Module's installation entry point.
     *
     * @param Module $module
     *
     * @return bool
     */
    public function install(Module $module): bool
    {
        if (!$this->registerHooks($module)) {
            return false;
        }

        if (!$this->installDatabase()) {
            return false;
        }

        return true;
    }

    /**
     * Module's uninstallation entry point.
     *
     * @return bool
     */
    public function uninstall(): bool
    {
        return $this->uninstallDatabase();
    }

    /**
     * Install the database modifications required for this module.
     *
     * @return bool
     */
    private function installDatabase(): bool
    {
        return $this->executeQueries(SqlQueries::installQueries());
    }

    /**
     * Uninstall database modifications.
     *
     * @return bool
     */
    private function uninstallDatabase(): bool
    {
        return $this->executeQueries(SqlQueries::uninstallQueries());
    }

    /**
     * Register hooks for the module.
     *
     * @param Module $module
     *
     * @return booldisplayOverrideTemplatedone
     */
    private function registerHooks(Module $module): bool
    {
        $hooks = [
            'actionCategoryFormBuilderModifier',
            'actionAfterCreateCategoryFormHandler',
            'actionAfterUpdateCategoryFormHandler',
            'displayOverrideTemplate',
            'displayHeader',
            'displayBackOfficeHeader'
        ];

        return (bool) $module->registerHook($hooks);
    }

    /**
     * A helper that executes multiple database queries.
     *
     * @param array $queries
     *
     * @return bool
     */
    private function executeQueries(array $queries): bool
    {
        foreach ($queries as $query) {
            if (!Db::getInstance()->execute($query)) {
                return false;
            }
        }

        return true;
    }
}
